={{ JSON.stringify({
  messaging_product: 'whatsapp',
  to: $json.telefono_whatsapp,
  type: 'template',
  template: {
    name: 'recordatorio_cita_es',
    language: { code: 'es' },
    components: [{
      type: 'body',
      parameters: [
        { type: 'text', text: $json.patient_nombre },
        { type: 'text', text: $json.clinic_nombre },
        { type: 'text', text: new Date($json.fecha_hora).toLocaleDateString('es-ES') },
        { type: 'text', text: new Date($json.fecha_hora).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' }) }
      ]
    }]
  }
}) }}

parameters.jsCode:
const entry = $json.body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
if (!message) return [];

const esBoton = message.type === 'button' || message.type === 'interactive';
const buttonId = message.button?.payload || message.interactive?.button_reply?.id || null;
const textoLibre = message.text?.body || null;

return [{ json: { wa_id: message.from, esBoton, buttonId, textoLibre } }];

parameters.jsonBody:
={{ JSON.stringify({
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'Un paciente respondió con texto libre a un recordatorio de cita. Clasifica en: confirma, cancela_o_reprograma, no_claro. Responde SOLO JSON {\"categoria\": string}.' },
    { role: 'user', content: $json.textoLibre }
  ]
}) }}

parameters.jsCode:
let categoria = 'no_claro';
try {
  const parsed = JSON.parse($json.choices[0].message.content);
  if (['confirma','cancela_o_reprograma','no_claro'].includes(parsed.categoria)) {
    categoria = parsed.categoria;
  }
} catch (e) { /* fail-safe: se queda en no_claro */ }

const mapa = { confirma: 'confirmada', cancela_o_reprograma: 'pendiente_reprogramacion', no_claro: 'alerta_manual' };
return [{ json: { nuevo_estado: mapa[categoria] } }];
